-- Final catalog enrichment pass for the remaining eight models. Sources verified 2026-09-07.
-- Covers Kimi K2.5, DeepSeek V4 Flash Vision Exp, Command A+, Jamba2 3B/Mini, MiniMax M2.5/M2.7 and ERNIE 5.1.

-- Remove a legacy mislabeled MiniMax score before merging corrected normalized evidence.
UPDATE models
SET comparison_data = COALESCE(comparison_data, '{}'::jsonb) - 'GDPval-AA v2',
    updated_at = NOW()
WHERE slug = 'minimax-m2-7';

INSERT INTO models (
  slug,name,developer,release_date,ga_date,access,family,
  comparison_data,sources,notes,metadata,verified_at
)
SELECT
  s.slug,s.name,s.developer,s.release_date::date,NULLIF(s.ga_date,'')::date,
  s.access,s.family,s.comparison_data,s.sources,s.notes,s.metadata,NOW()
FROM jsonb_to_recordset($models$
