$benchmarks$::jsonb) AS b(
  model_slug text,category text,benchmark_name text,benchmark_version text,
  score_numeric double precision,score_display text,score_unit text,tools boolean,
  reasoning_effort text,harness text,evaluator text,evaluation_date text,source text,notes text
)
ON CONFLICT (id) DO UPDATE SET
  model_slug=EXCLUDED.model_slug,
  category=EXCLUDED.category,
  benchmark_name=EXCLUDED.benchmark_name,
  benchmark_version=EXCLUDED.benchmark_version,
  score_numeric=EXCLUDED.score_numeric,
  score_display=EXCLUDED.score_display,
  score_unit=EXCLUDED.score_unit,
  tools=EXCLUDED.tools,
  reasoning_effort=EXCLUDED.reasoning_effort,
  harness=EXCLUDED.harness,
  evaluator=EXCLUDED.evaluator,
  evaluation_date=EXCLUDED.evaluation_date,
  source=EXCLUDED.source,
  notes=EXCLUDED.notes,
  updated_at=NOW();

-- Preserve authored comparison cells: populate normalized benchmark evidence only where the cell is blank.
WITH r AS (
  SELECT
    b.model_slug,b.benchmark_name,b.evaluation_date,b.id,
    b.score_display ||
    CASE WHEN concat_ws('; ',
      CASE
        WHEN b.benchmark_version IS NOT NULL
         AND lower(trim(b.benchmark_version)) <> 'public'
         AND position(lower(b.benchmark_version) in lower(b.benchmark_name)) = 0
        THEN b.benchmark_version
      END,
      CASE WHEN b.tools IS TRUE THEN 'tools' WHEN b.tools IS FALSE THEN 'no tools' END,
      b.reasoning_effort
    ) <> ''
    THEN ' (' || concat_ws('; ',
      CASE
        WHEN b.benchmark_version IS NOT NULL
         AND lower(trim(b.benchmark_version)) <> 'public'
         AND position(lower(b.benchmark_version) in lower(b.benchmark_name)) = 0
        THEN b.benchmark_version
      END,
      CASE WHEN b.tools IS TRUE THEN 'tools' WHEN b.tools IS FALSE THEN 'no tools' END,
      b.reasoning_effort
    ) || ')'
    ELSE '' END AS rendered
  FROM model_benchmarks b
  WHERE b.model_slug IN ('kimi-k2-5','deepseek-v4-flash-vision-exp','command-a-plus','jamba2-3b','jamba2-mini','minimax-m2-5','minimax-m2-7','ernie-5-1')
),
g AS (
  SELECT model_slug,benchmark_name,
         string_agg(rendered,' · ' ORDER BY evaluation_date NULLS LAST,id) AS rendered
  FROM r
  GROUP BY model_slug,benchmark_name
),
x AS (
  SELECT c.id,
    jsonb_agg(
      CASE WHEN jsonb_typeof(be.block->'rows')='array'
      THEN jsonb_set(
        be.block,'{rows}',
        COALESCE((
          SELECT jsonb_agg(
            CASE
              WHEN jsonb_typeof(re.row_value)='array' AND jsonb_array_length(re.row_value)>=3
              THEN jsonb_set(
                jsonb_set(
                  re.row_value,'{1}',
                  to_jsonb(CASE
                    WHEN COALESCE(re.row_value->>1,'')='' AND a.rendered IS NOT NULL
                    THEN a.rendered ELSE COALESCE(re.row_value->>1,'')
                  END),false
                ),
                '{2}',
                to_jsonb(CASE
                  WHEN COALESCE(re.row_value->>2,'')='' AND d.rendered IS NOT NULL
                  THEN d.rendered ELSE COALESCE(re.row_value->>2,'')
                END),false
              )
              ELSE re.row_value
            END
            ORDER BY re.ord
          )
          FROM jsonb_array_elements(be.block->'rows') WITH ORDINALITY re(row_value,ord)
          LEFT JOIN g a ON a.model_slug=c.metadata->>'modelA'
                       AND lower(a.benchmark_name)=lower(COALESCE(re.row_value->>0,''))
          LEFT JOIN g d ON d.model_slug=c.metadata->>'modelB'
                       AND lower(d.benchmark_name)=lower(COALESCE(re.row_value->>0,''))
        ),'[]'::jsonb),
        true
      )
      ELSE be.block END
      ORDER BY be.ord
    ) AS blocks
  FROM content_items c
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.blocks,'[]'::jsonb))
    WITH ORDINALITY be(block,ord)
  WHERE c.kind='comparison'
    AND (
      c.metadata->>'modelA' IN ('kimi-k2-5','deepseek-v4-flash-vision-exp','command-a-plus','jamba2-3b','jamba2-mini','minimax-m2-5','minimax-m2-7','ernie-5-1')
      OR c.metadata->>'modelB' IN ('kimi-k2-5','deepseek-v4-flash-vision-exp','command-a-plus','jamba2-3b','jamba2-mini','minimax-m2-5','minimax-m2-7','ernie-5-1')
    )
  GROUP BY c.id,c.metadata
)
UPDATE content_items c
SET blocks=x.blocks,updated_at=NOW()
FROM x
WHERE c.id=x.id AND c.blocks IS DISTINCT FROM x.blocks;
